-- Catálogo de campos de golf de México para poder anfitrionar en cualquiera
-- de ellos, con dirección/coordenadas conectadas a Google Maps.
--
-- tipo 'publico': campos públicos/turísticos/resort y semi-privados
-- (gogolf.mx + Federación Mexicana de Golf).
-- tipo 'privado': clubes de golf de membresía — el segmento al que
-- realmente aplica el intercambio de tee times entre socios.
--
-- Fuentes:
--  - gogolf.mx (API pública /api/v1/maps/all-fields/): dirección postal
--    exacta tal como la publican ellos.
--  - Federación Mexicana de Golf, mapa oficial "Campos de Golf Federados
--    en México" (Google My Maps, KML público): coordenadas exactas pero
--    sin dirección postal ni ciudad — el estado se estimó por cercanía
--    cuando el KML no lo daba, puede haber algún error puntual cerca de
--    límites estatales.
--  - Un puñado de clubes privados conocidos compilados de conocimiento
--    general (no verificados con una fuente única) — su dirección es una
--    cadena de búsqueda (nombre + ciudad + estado), no una dirección
--    postal exacta.
--
-- Corrige cualquier entrada directamente en Supabase Studio si necesitas
-- precisión exacta antes del piloto real — ver lib/data/clubs-mexico.ts,
-- la fuente de la que se generó este INSERT (también usada en el modo
-- demo y el seed de prueba).

alter table public.clubs
  add column if not exists estado text,
  add column if not exists direccion text,
  add column if not exists tipo text not null default 'privado' check (tipo in ('privado', 'publico')),
  add column if not exists latitud numeric(10, 7),
  add column if not exists longitud numeric(10, 7);

-- total: 166 clubes
